"""Markdown rendering of a run snapshot, one section per declared agent output."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any

from agents.hooks.specs import AGENT_SPECS

REPORT_DISCLAIMER = (
    "> Generated by LLM agents for research and educational use only. "
    "This is not investment advice."
)
REPORT_AGENT_ORDER = (
    "fundamentals_analyst",
    "market_analyst",
    "news_analyst",
    "analyst_coordinator",
    "bull_researcher",
    "bear_researcher",
    "research_manager",
    "trader",
    "aggressive_risk_analyst",
    "conservative_risk_analyst",
    "neutral_risk_analyst",
    "risk_manager",
    "investment_manager",
)


def render_report(values: Mapping[str, Any]) -> str:
    parts = [
        f"# Investment Report for {values['ticker']} on {values['current_date']}",
        f"Run: {values['run_id']}",
        "> Analysis snapshot. Consult manifest.json or run.sqlite3 for the committed run outcome.",
        REPORT_DISCLAIMER,
    ]
    # One section per declared agent output; aliases are not duplicate sections.
    for agent_id in REPORT_AGENT_ORDER:
        spec = AGENT_SPECS[agent_id]
        key = spec.output_keys[0]
        if key in values:
            parts.append(f"## {key.replace('_', ' ').title()}\n\n{values[key]}")
    return "\n\n".join(parts) + "\n"
